import json
g=json.load(open('/work/graph.json'))
from collections import defaultdict
adj=defaultdict(list)
for r in g['runs']:adj[r['a']].append(r['b']);adj[r['b']].append(r['a'])
def comp(p):
    seen={p};st=[p]
    while st:
        x=st.pop()
        for y in adj[x]:
            if y not in seen:seen.add(y);st.append(y)
    return sorted(seen,key=lambda s:int(s[1:]))
done=set()
for p in g['points']:
    if p['id'] in done or int(p['id'][1:])>294:continue
    c=comp(p['id']);done|=set(c)
    print(c)
